import psutil
import time
import sys

def monitor_process(pid, interval=1):
    try:
        process = psutil.Process(pid)
        while True:
            cpu = process.cpu_percent(interval=0.5)
            mem = process.memory_info().rss / 1024 / 1024
            print(f'CPU: {cpu:.1f}% | Memória: {mem:.1f} MB')
            time.sleep(interval)
    except psutil.NoSuchProcess:
