import (
	"context"
	"fmt"
	"io"
	"net/http"
	"time"
)

func httpGetWithRetry(ctx context.Context, url string, maxRetries int) ([]byte, error) {
	var lastErr error
	backoff := time.Second
	for attempt := 0; attempt <= maxRetries; attempt++ {
		if attempt > 0 {
			select {
			case <-ctx.Done():
				return nil, ctx.Err()
			case <-time.After(backoff):
				backoff *= 2
				if backoff > 30*time.Second {
					backoff = 30 * time.Second
				}
			}
		}
		req, err := http.NewRequestWithContext(ctx, "GET", url, nil)
		if err != nil {
			return nil, err
		}
		resp, err := http.DefaultClient.Do(req)
		if err != nil {
			lastErr = err
			continue
		}
		defer resp.Body.Close()
		if resp.StatusCode >= 500 {
			lastErr = fmt.Errorf("erro do servidor: %d", resp.StatusCode)
			continue
		}
		return io.ReadAll(resp.Body)
	}
	return nil, fmt.Errorf("falhou após %d tentativas: %w", maxRetries, lastErr)
}

import { Request, Response, NextFunction } from 'express';

interface RateLimitStore {
  [key: string]: { count: number; resetTime: number };
}

const store: RateLimitStore = {};

export function rateLimit(windowMs: number = 60000, maxRequests: number = 100) {
  return (req: Request, res: Response, next: NextFunction) => {
    const key = req.ip || 'unknown';
    const now = Date.now();
    if (!store[key] || now > store[key].resetTime) {
      store[key] = { count: 1, resetTime: now + windowMs };
    } else {
      store[key].count++;
    }
    const remaining = maxRequests - store[key].count;
    res.setHeader('X-RateLimit-Limit', String(maxRequests));
    res.setHeader('X-RateLimit-Remaining', String(Math.max(0, remaining)));
    res.setHeader('X-RateLimit-Reset', String(store[key].resetTime));
    if (store[key].count > maxRequests) {
      return res.status(429).json({ error: 'Muitas requisições, tente novamente mais tarde' });
    }
    next();
  };
}

setInterval(() => {
  const now = Date.now();
  Object.keys(store).forEach(key => {
    if (now > store[key].resetTime) {
      delete store[key];
    }
  });
}, 300000);

#!/usr/bin/env python3
import re
from collections import Counter
import json

LOG_PATTERN = re.compile(r'^(\S+) - - \[(.+?)\] "(\S+) (\S+) \S+" (\d{3}) (\S+)')

def parse_log_line(line):
    match = LOG_PATTERN.match(line)
    if not match:
        return None
    ip, date_str, method, path, status, size = match.groups()
    return {
        'ip': ip,
        'method': method,
        'path': path,
        'status': int(status),
        'size': int(size) if size != '-' else 0
    }

def analyze_log(log_file):
    entries = []
    with open(log_file, 'r') as f:
        for line in f:
            entry = parse_log_line(line)
            if entry:
                entries.append(entry)
    if not entries:
        print('Nenhuma entrada válida encontrada.')
        return
    stats = {
        'total_requests': len(entries),
        'unique_ips': len(set(e['ip'] for e in entries)),
        'status_codes': dict(Counter(e['status'] for e in entries)),
        'top_paths': Counter(e['path'] for e in entries).most_common(10),
        'top_ips': Counter(e['ip'] for e in entries).most_common(10),
        'methods': dict(Counter(e['method'] for e in entries)),
    }
    print(json.dumps(stats, indent=2))

if __name__ == '__main__':
    analyze_log('/var/log/nginx/access.log')

use std::collections::HashMap;
use std::fs::File;
use std::io::{self, BufRead, BufReader, Write};

fn main() -> io::Result<()> {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 3 {
        eprintln!("Uso: {} <input.csv> <output.json>", args[0]);
        std::process::exit(1);
    }
    let input = &args[1];
    let output = &args[2];
    let file = File::open(input)?;
    let reader = BufReader::new(file);
    let mut lines = reader.lines();
    let headers: Vec<String> = lines
        .next()
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "CSV vazio"))??
        .split(',')
        .map(|s| s.trim().to_string())
        .collect();
    let mut records = Vec::new();
    for line in lines {
        let line = line?;
        let values: Vec<String> = line.split(',').map(|s| s.trim().to_string()).collect();
        let mut record = HashMap::new();
        for (i, header) in headers.iter().enumerate() {
            record.insert(header.clone(), values.get(i).cloned().unwrap_or_default());
        }
        records.push(record);
    }
    let json = serde_json::to_string_pretty(&records)?;
    let mut file = File::create(output)?;
    file.write_all(json.as_bytes())?;
    println!("Convertido {} registros para {}", records.len(), output);
    Ok(())
}

package cache

import (
	"container/list"
	"sync"
)

type LRUCache struct {
	capacity int
	cache    map[string]*list.Element
	lru      *list.List
	mu       sync.RWMutex
}

type entry struct {
	key   string
	value interface{}
}

func NewLRU(capacity int) *LRUCache {
	return &LRUCache{
		capacity: capacity,
		cache:    make(map[string]*list.Element),
		lru:      list.New(),
	}
}

func (c *LRUCache) Get(key string) (interface{}, bool) {
	c.mu.RLock()
	elem, ok := c.cache[key]
	c.mu.RUnlock()
	if !ok {
		return nil, false
	}
	c.mu.Lock()
	c.lru.MoveToFront(elem)
	c.mu.Unlock()
	return elem.Value.(*entry).value, true
}

func (c *LRUCache) Set(key string, value interface{}) {
	c.mu.Lock()
	defer c.mu.Unlock()
	if elem, ok := c.cache[key]; ok {
		c.lru.MoveToFront(elem)
		elem.Value.(*entry).value = value
		return
	}
	elem := c.lru.PushFront(&entry{key, value})
	c.cache[key] = elem
	if c.lru.Len() > c.capacity {
		oldest := c.lru.Back()
		c.lru.Remove(oldest)
		delete(c.cache, oldest.Value.(*entry).key)
	}
}

func (c *LRUCache) Len() int {
	c.mu.RLock()
	defer c.mu.RUnlock()
	return c.lru.Len()
}

import jwt from 'jsonwebtoken';
import crypto from 'crypto';

interface TokenPair {
  accessToken: string;
  refreshToken: string;
  expiresIn: number;
}

interface TokenPayload {
  userId: string;
  email: string;
  role: string;
}

export class TokenService {
  private accessSecret: string;
  private refreshTokens: Map<string, string>;

  constructor() {
    this.accessSecret = process.env.JWT_ACCESS_SECRET || crypto.randomUUID();
    this.refreshTokens = new Map();
  }

  generateTokens(payload: TokenPayload): TokenPair {
    const accessToken = jwt.sign(payload, this.accessSecret, {
      expiresIn: '15m',
    });
    const refreshToken = crypto.randomBytes(40).toString('hex');
    const expiresIn = 7 * 24 * 60 * 60 * 1000;
    this.refreshTokens.set(refreshToken, payload.userId);
    return { accessToken, refreshToken, expiresIn };
  }

  verifyAccessToken(token: string): TokenPayload | null {
    try {
      return jwt.verify(token, this.accessSecret) as TokenPayload;
    } catch {
      return null;
    }
  }

  refreshAccessToken(refreshToken: string): TokenPair | null {
    const userId = this.refreshTokens.get(refreshToken);
    if (!userId) return null;
    const payload = { userId, email: '', role: '' };
    this.revokeRefreshToken(refreshToken);
    return this.generateTokens(payload);
  }

  revokeRefreshToken(token: string): void {
    this.refreshTokens.delete(token);
  }
}

#!/usr/bin/env python3
import os
import shutil
import hashlib
from pathlib import Path

def file_hash(filepath):
    sha256 = hashlib.sha256()
    with open(filepath, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            sha256.update(chunk)
    return sha256.hexdigest()

def sync_directories(source, dest, delete=False, dry_run=True):
    source_path = Path(source)
    dest_path = Path(dest)
    operations = {'copied': [], 'updated': [], 'deleted': [], 'unchanged': []}
    for src_file in source_path.rglob('*'):
        if not src_file.is_file():
            continue
        rel_path = src_file.relative_to(source_path)
        dst_file = dest_path / rel_path
        dst_file.parent.mkdir(parents=True, exist_ok=True)
        if not dst_file.exists():
            if not dry_run:
                shutil.copy2(src_file, dst_file)
            operations['copied'].append(str(rel_path))
        elif file_hash(src_file) != file_hash(dst_file):
            if not dry_run:
                shutil.copy2(src_file, dst_file)
            operations['updated'].append(str(rel_path))
        else:
            operations['unchanged'].append(str(rel_path))
    if delete:
        for dst_file in dest_path.rglob('*'):
            if not dst_file.is_file():
                continue
            rel_path = dst_file.relative_to(dest_path)
            src_file = source_path / rel_path
            if not src_file.exists():
                if not dry_run:
                    dst_file.unlink()
                operations['deleted'].append(str(rel_path))
    return operations

if __name__ == '__main__':
    ops = sync_directories('/home/user/docs', '/backup/docs', delete=True, dry_run=False)
    print(f"Copiados: {len(ops['copied'])}, Atualizados: {len(ops['updated'])}, Excluídos: {len(ops['deleted'])}")

use std::collections::VecDeque;
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Duration, Instant};

#[derive(Debug, Clone)]
struct SensorReading {
    sensor_id: String,
    timestamp: Instant,
    value: f64,
}

struct SensorProcessor {
    buffer: Arc<Mutex<VecDeque<SensorReading>>>,
    window_size: usize,
}

impl SensorProcessor {
    fn new(window_size: usize) -> Self {
        SensorProcessor {
            buffer: Arc::new(Mutex::new(VecDeque::with_capacity(window_size * 2))),
            window_size,
        }
    }

    fn add_reading(&self, reading: SensorReading) {
        let mut buffer = self.buffer.lock().unwrap();
        buffer.push_back(reading);
        if buffer.len() > self.window_size {
            buffer.pop_front();
        }
    }

    fn moving_average(&self) -> Option<f64> {
        let buffer = self.buffer.lock().unwrap();
        if buffer.is_empty() {
            return None;
        }
        let sum: f64 = buffer.iter().map(|r| r.value).sum();
        Some(sum / buffer.len() as f64)
    }

    fn start_processing(&self, rx: std::sync::mpsc::Receiver<SensorReading>) {
        let buffer = Arc::clone(&self.buffer);
        thread::spawn(move || {
            while let Ok(reading) = rx.recv() {
                let mut buf = buffer.lock().unwrap();
                buf.push_back(reading);
                if buf.len() > 10 {
                    buf.pop_front();
                }
                let avg: f64 = buf.iter().map(|r| r.value).sum::<f64>() / buf.len() as f64;
                println!("Média móvel: {:.2}", avg);
            }
        });
    }
}

