package worker

import (
	"context"
	"sync"
)

type Task func() error

type WorkerPool struct {
	workers    int
	queue      chan Task
	results    chan error
	wg         sync.WaitGroup
	ctx        context.Context
	cancel     context.CancelFunc
}

func NewWorkerPool(workers, queueSize int) *WorkerPool {
	ctx, cancel := context.WithCancel(context.Background())
	return &WorkerPool{
		workers: workers,
		queue:   make(chan Task, queueSize),
		results: make(chan error, queueSize),
		ctx:     ctx,
		cancel:  cancel,
	}
}

func (p *WorkerPool) Start() {
	for i := 0; i < p.workers; i++ {
		p.wg.Add(1)
		go p.worker(i)
	}
}

func (p *WorkerPool) worker(id int) {
	defer p.wg.Done()
	for {
		select {
		case task := <-p.queue:
			if task == nil {
				return
			}
			p.results <- task()
		case <-p.ctx.Done():
			return
		}
	}
}

func (p *WorkerPool) Submit(task Task) bool {
	select {
	case p.queue <- task:
		return true
	case <-p.ctx.Done():
		return false
	}
}

func (p *WorkerPool) Stop() []error {
	close(p.queue)
	p.wg.Wait()
	close(p.results)
	var errors []error
	for err := range p.results {
		if err != nil {
			errors = append(errors, err)
		}
	}
	return errors
}

interface ArgOptions {
  [key: string]: {
    type: 'string' | 'number' | 'boolean';
    alias?: string;
    default?: any;
    required?: boolean;
  };
}

interface ParsedArgs {
  [key: string]: any;
  _: string[];
}

export class ArgParser {
  private options: ArgOptions;

  constructor(options: ArgOptions) {
    this.options = options;
  }

  parse(args: string[] = process.argv.slice(2)): ParsedArgs {
    const result: ParsedArgs = { _: [] };
    let i = 0;
    while (i < args.length) {
      const arg = args[i];
      if (arg === '--') {
        result._.push(...args.slice(i + 1));
        break;
      }
      if (arg.startsWith('--')) {
        const name = arg.slice(2);
        const option = this.options[name];
        if (option) {
          i = this.parseOption(args, i, option, name, result);
        }
      } else if (arg.startsWith('-') && arg.length > 1) {
        const alias = arg.slice(1);
        const option = Object.entries(this.options).find(([_, v]) => v.alias === alias)?.[1];
        if (option) {
          i = this.parseOption(args, i, option, alias, result);
        }
      } else {
        result._.push(arg);
      }
      i++;
    }
    for (const [key, config] of Object.entries(this.options)) {
      if (!(key in result) && 'default' in config) {
        result[key] = config.default;
      }
      if (config.required && !(key in result)) {
        throw new Error(`Opção obrigatória: ${key}`);
      }
    }
    return result;
  }

  private parseOption(args: string[], i: number, option: any, name: string, result: ParsedArgs): number {
    if (option.type === 'boolean') {
      result[name] = true;
      return i;
    }
    const value = args[++i];
    if (!value || value.startsWith('-')) {
      throw new Error(`Valor necessário para: ${name}`);
    }
    if (option.type === 'number') {
      const num = parseFloat(value);
      if (isNaN(num)) {
        throw new Error(`Número inválido para ${name}: ${value}`);
      }
      result[name] = num;
    } else {
      result[name] = value;
    }
    return i;
  }
}

#!/usr/bin/env python3
import PyPDF2
from pathlib import Path
import json

def extract_pdf_metadata(filepath):
    try:
        with open(filepath, 'rb') as f:
            reader = PyPDF2.PdfReader(f)
            info = reader.metadata
            metadata = {
                'filename': Path(filepath).name,
                'pages': len(reader.pages),
                'title': info.title if info else None,
                'author': info.author if info else None,
                'subject': info.subject if info else None,
                'creator': info.creator if info else None,
                'producer': info.producer if info else None,
                'encrypted': reader.is_encrypted,
                'file_size_bytes': Path(filepath).stat().st_size,
            }
            if len(reader.pages) > 0 and not reader.is_encrypted:
                try:
                    first_page = reader.pages[0]
                    text_sample = first_page.extract_text()[:500] if first_page.extract_text() else ''
                    metadata['text_sample'] = text_sample + '...' if len(text_sample) == 500 else text_sample
                except:
                    metadata['text_sample'] = None
            return metadata
    except Exception as e:
        return {'error': str(e), 'filename': filepath}

def scan_directory(directory):
    results = []
    for pdf_file in Path(directory).glob('**/*.pdf'):
        results.append(extract_pdf_metadata(pdf_file))
    return results

if __name__ == '__main__':
    import sys
    if len(sys.argv) < 2:
        print('Uso: python pdf_metadata.py <diretório>')
        sys.exit(1)
    data = scan_directory(sys.argv[1])
    print(json.dumps(data, indent=2, ensure_ascii=False))

use std::fmt;
use std::io::{self, Write};
use std::sync::{Arc, Mutex};
use std::time::{SystemTime, UNIX_EPOCH};
use serde::Serialize;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum LogLevel {
    Debug,
    Info,
    Warn,
    Error,
    Fatal,
}

impl fmt::Display for LogLevel {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            LogLevel::Debug => write!(f, "DEBUG"),
            LogLevel::Info => write!(f, "INFO"),
            LogLevel::Warn => write!(f, "WARN"),
            LogLevel::Error => write!(f, "ERROR"),
            LogLevel::Fatal => write!(f, "FATAL"),
        }
    }
}

#[derive(Serialize)]
struct LogEntry {
    timestamp: u64,
    level: String,
    message: String,
}

pub struct Logger {
    level: LogLevel,
    json_format: bool,
}

impl Logger {
    pub fn new(level: LogLevel) -> Self {
        Logger { level, json_format: false }
    }

    pub fn with_json(mut self) -> Self {
        self.json_format = true;
        self
    }

    pub fn log(&self, level: LogLevel, message: &str) {
        if level < self.level {
            return;
        }
        let timestamp = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_secs();
        if self.json_format {
            let entry = LogEntry {
                timestamp,
                level: level.to_string(),
                message: message.to_string(),
            };
            println!("{}", serde_json::to_string(&entry).unwrap());
        } else {
            println!("[{}] {}: {}", timestamp, level, message);
        }
    }

    pub fn info(&self, message: &str) {
        self.log(LogLevel::Info, message);
    }

    pub fn error(&self, message: &str) {
        self.log(LogLevel::Error, message);
    }
}

package main

import (
	"log"
	"net/http"
	"sync"
	"github.com/gorilla/websocket"
)

var upgrader = websocket.Upgrader{
	CheckOrigin: func(r *http.Request) bool {
		return true
	},
}

type Hub struct {
	clients    map[*Client]bool
	broadcast  chan []byte
	register   chan *Client
	unregister chan *Client
	mu         sync.RWMutex
}

type Client struct {
	hub  *Hub
	conn *websocket.Conn
	send chan []byte
}

func newHub() *Hub {
	return &Hub{
		clients:    make(map[*Client]bool),
		broadcast:  make(chan []byte),
		register:   make(chan *Client),
		unregister: make(chan *Client),
	}
}

func (h *Hub) run() {
	for {
		select {
		case client := <-h.register:
			h.mu.Lock()
			h.clients[client] = true
			h.mu.Unlock()
		case client := <-h.unregister:
			h.mu.Lock()
			if _, ok := h.clients[client]; ok {
				delete(h.clients, client)
				close(client.send)
			}
			h.mu.Unlock()
		case message := <-h.broadcast:
			h.mu.RLock()
			for client := range h.clients {
				select {
				case client.send <- message:
				default:
					close(client.send)
					delete(h.clients, client)
				}
			}
			h.mu.RUnlock()
		}
	}
}

func serveWs(hub *Hub, w http.ResponseWriter, r *http.Request) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Println(err)
		return
	}
	client := &Client{hub: hub, conn: conn, send: make(chan []byte, 256)}
	client.hub.register <- client
	go client.writePump()
	go client.readPump()
}

import { createWriteStream, existsSync, mkdirSync } from 'fs';
import { join } from 'path';
import { createHash } from 'crypto';
import { pipeline } from 'stream/promises';
import { Readable } from 'stream';

interface UploadConfig {
  maxFileSize: number;
  allowedMimeTypes: string[];
  uploadDir: string;
}

interface UploadResult {
  filename: string;
  originalName: string;
  size: number;
  mimeType: string;
  hash: string;
  path: string;
}

export class FileUploadService {
  private config: UploadConfig;

  constructor(config: UploadConfig) {
    this.config = config;
    this.ensureUploadDir();
  }

  private ensureUploadDir(): void {
    if (!existsSync(this.config.uploadDir)) {
      mkdirSync(this.config.uploadDir, { recursive: true });
    }
  }

  private validateFile(buffer: Buffer, mimeType: string): void {
    if (buffer.length > this.config.maxFileSize) {
      throw new Error('Arquivo muito grande');
    }
    if (!this.config.allowedMimeTypes.includes(mimeType)) {
      throw new Error('Tipo de arquivo não permitido');
    }
  }

  private generateFilename(originalName: string, hash: string): string {
    const timestamp = Date.now();
    const sanitized = originalName.replace(/[^a-zA-Z0-9.-]/g, '_');
    return `${timestamp}-${sanitized}`;
  }

  async upload(buffer: Buffer, originalName: string, mimeType: string): Promise<UploadResult> {
    this.validateFile(buffer, mimeType);
    const hash = createHash('sha256').update(buffer).digest('hex');
    const filename = this.generateFilename(originalName, hash);
    const filepath = join(this.config.uploadDir, filename);
    const stream = Readable.from([buffer]);
    const writeStream = createWriteStream(filepath);
    await pipeline(stream, writeStream);
    return {
      filename,
      originalName,
      size: buffer.length,
      mimeType,
      hash,
      path: filepath
    };
  }
}

use std::collections::HashMap;
use std::fs;
use std::path::Path;

#[derive(Debug, Clone)]
pub enum ConfigValue {
    String(String),
    Integer(i64),
    Float(f64),
    Boolean(bool),
    List(Vec<ConfigValue>),
    Section(HashMap<String, ConfigValue>),
}

pub struct ConfigParser;

impl ConfigParser {
    pub fn parse_file<P: AsRef<Path>>(path: P) -> Result<HashMap<String, ConfigValue>, String> {
        let content = fs::read_to_string(path).map_err(|e| e.to_string())?;
        Self::parse(&content)
    }

    pub fn parse(content: &str) -> Result<HashMap<String, ConfigValue>, String> {
        let mut config = HashMap::new();
        let mut current_section: Option<String> = None;
        let mut section_data: HashMap<String, ConfigValue> = HashMap::new();
        for (line_num, line) in content.lines().enumerate() {
            let line = line.trim();
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            if line.starts_with('[') && line.ends_with(']') {
                if let Some(ref section) = current_section {
                    config.insert(section.clone(), ConfigValue::Section(section_data.clone()));
                }
                current_section = Some(line[1..line.len()-1].to_string());
                section_data.clear();
                continue;
            }
            if let Some(pos) = line.find('=') {
                let key = line[..pos].trim().to_string();
                let value = line[pos+1..].trim();
                let parsed_value = Self::parse_value(value)?;
                if let Some(ref section) = current_section {
                    section_data.insert(key, parsed_value);
                } else {
                    config.insert(key, parsed_value);
                }
            }
        }
        if let Some(section) = current_section {
            config.insert(section, ConfigValue::Section(section_data));
        }
        Ok(config)
    }

    fn parse_value(value: &str) -> Result<ConfigValue, String> {
        if value.eq_ignore_ascii_case("true") {
            return Ok(ConfigValue::Boolean(true));
        }
        if value.eq_ignore_ascii_case("false") {
            return Ok(ConfigValue::Boolean(false));
        }
        if value.starts_with('[') && value.ends_with(']') {
            let items: Result<Vec<_>, _> = value[1..value.len()-1]
                .split(',')
                .map(|s| Self::parse_value(s.trim()))
                .collect();
            return Ok(ConfigValue::List(items?));
        }
        if let Ok(i) = value.parse::<i64>() {
            return Ok(ConfigValue::Integer(i));
        }
        if let Ok(f) = value.parse::<f64>() {
            return Ok(ConfigValue::Float(f));
        }
        let s = if (value.starts_with('"') && value.ends_with('"')) ||
                   (value.starts_with("'") && value.ends_with("'")) {
            value[1..value.len()-1].to_string()
        } else {
            value.to_string()
        };
        Ok(ConfigValue::String(s))
    }
}

package cache

import (
	"context"
	"encoding/json"
	"fmt"
	"sync"
	"time"
)

type Item struct {
	Value      interface{}
	Expiration int64
}

type DistributedCache struct {
	local     *LocalCache
	remotes   []CacheClient
	replicate bool
}

type LocalCache struct {
	items map[string]Item
	mu    sync.RWMutex
}

type CacheClient interface {
	Get(ctx context.Context, key string) ([]byte, error)
	Set(ctx context.Context, key string, value []byte, ttl time.Duration) error
	Delete(ctx context.Context, key string) error
}

func NewLocalCache() *LocalCache {
	c := &LocalCache{items: make(map[string]Item)}
	go c.cleanup()
	return c
}

func (c *LocalCache) cleanup() {
	ticker := time.NewTicker(time.Minute)
	for range ticker.C {
		c.mu.Lock()
		now := time.Now().UnixNano()
		for k, v := range c.items {
			if v.Expiration > 0 && now > v.Expiration {
				delete(c.items, k)
			}
		}
		c.mu.Unlock()
	}
}

func (c *LocalCache) Set(key string, value interface{}, ttl time.Duration) {
	c.mu.Lock()
	defer c.mu.Unlock()
	expiration := int64(0)
	if ttl > 0 {
		expiration = time.Now().Add(ttl).UnixNano()
	}
	c.items[key] = Item{Value: value, Expiration: expiration}
}

func (c *LocalCache) Get(key string) (interface{}, bool) {
	c.mu.RLock()
	defer c.mu.RUnlock()
	item, found := c.items[key]
	if !found {
		return nil, false
	}
	if item.Expiration > 0 && time.Now().UnixNano() > item.Expiration {
		return nil, false
	}
	return item.Value, true
}

func (c *LocalCache) Delete(key string) {
	c.mu.Lock()
	defer c.mu.Unlock()
	delete(c.items, key)
}

func (dc *DistributedCache) Set(ctx context.Context, key string, value interface{}, ttl time.Duration) error {
	dc.local.Set(key, value, ttl)
	if dc.replicate {
		data, err := json.Marshal(value)
		if err != nil {
			return err
		}
		for _, remote := range dc.remotes {
			if err := remote.Set(ctx, key, data, ttl); err != nil {
				fmt.Printf("Erro ao replicar: %v\n", err)
			}
		}
	}
	return nil
}

import { Request, Response, NextFunction } from 'express';

interface ValidationSchema {
  [key: string]: {
    type: 'string' | 'number' | 'boolean' | 'array' | 'object' | 'email' | 'url';
    required?: boolean;
    min?: number;
    max?: number;
    pattern?: RegExp;
    enum?: any[];
    custom?: (value: any) => string | null;
  };
}

interface ValidationError {
  field: string;
  message: string;
  value?: any;
}

export class SchemaValidator {
  static validate(schema: ValidationSchema) {
    return (req: Request, res: Response, next: NextFunction): void => {
      const data = { ...req.body, ...req.query, ...req.params };
      const errors: ValidationError[] = [];
      for (const [field, rules] of Object.entries(schema)) {
        const value = data[field];
        const error = this.validateField(field, value, rules);
        if (error) {
          errors.push({ field, message: error, value });
        }
      }
      if (errors.length > 0) {
        res.status(400).json({ success: false, errors });
        return;
      }
      next();
    };
  }

  private static validateField(field: string, value: any, rules: ValidationSchema[string]): string | null {
    if (rules.required && (value === undefined || value === null || value === '')) {
      return `O campo '${field}' é obrigatório`;
    }
    if (value === undefined || value === null) {
      return null;
    }
    const typeError = this.validateType(value, rules.type, field);
    if (typeError) return typeError;
    if (rules.type === 'string' || rules.type === 'email') {
      const strValue = String(value);
      if (rules.min !== undefined && strValue.length < rules.min) {
        return `Mínimo ${rules.min} caracteres`;
      }
      if (rules.max !== undefined && strValue.length > rules.max) {
        return `Máximo ${rules.max} caracteres`;
      }
    }
    if (rules.type === 'number') {
      const numValue = Number(value);
      if (rules.min !== undefined && numValue < rules.min) {
        return `Valor mínimo: ${rules.min}`;
      }
      if (rules.max !== undefined && numValue > rules.max) {
        return `Valor máximo: ${rules.max}`;
      }
    }
    if (rules.enum !== undefined && !rules.enum.includes(value)) {
      return `Valores permitidos: ${rules.enum.join(', ')}`;
    }
    if (rules.pattern && !rules.pattern.test(String(value))) {
      return 'Formato inválido';
    }
    if (rules.custom) {
      const customError = rules.custom(value);
      if (customError) return customError;
    }
    return null;
  }

  private static validateType(value: any, type: string, field: string): string | null {
    switch (type) {
      case 'string':
        if (typeof value !== 'string') return `${field} deve ser uma string`;
        break;
      case 'number':
        if (typeof value !== 'number' || isNaN(value)) return `${field} deve ser um número`;
        break;
      case 'boolean':
        if (typeof value !== 'boolean') return `${field} deve ser um booleano`;
        break;
      case 'email':
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailRegex.test(String(value))) return `${field} deve ser um email válido`;
        break;
      case 'url':
        try {
          new URL(String(value));
        } catch {
          return `${field} deve ser uma URL válida`;
        }
        break;
      case 'array':
        if (!Array.isArray(value)) return `${field} deve ser um array`;
        break;
      case 'object':
        if (typeof value !== 'object' || value === null || Array.isArray(value)) {
          return `${field} deve ser um objeto`;
        }
        break;
    }
    return null;
  }
}

#!/usr/bin/env python3
import json
import subprocess
from collections import defaultdict
from typing import Dict, List, Optional

class DependencyAnalyzer:
    def __init__(self, package_manager='pip'):
        self.package_manager = package_manager
        self.dependencies = defaultdict(set)

    def get_installed_packages(self) -> List[Dict]:
        if self.package_manager == 'pip':
            result = subprocess.run(
                ['pip', 'list', '--format=json'],
                capture_output=True, text=True
            )
            return json.loads(result.stdout) if result.returncode == 0 else []
        return []

    def get_package_info(self, package_name: str) -> Optional[Dict]:
        if self.package_manager == 'pip':
            result = subprocess.run(
                ['pip', 'show', package_name],
                capture_output=True, text=True
            )
            return self._parse_pip_show(result.stdout) if result.stdout else None
        return None

    def _parse_pip_show(self, output: str) -> Optional[Dict]:
        info = {}
        for line in output.strip().split('\n'):
            if ':' in line:
                key, value = line.split(':', 1)
                key = key.strip().lower()
                value = value.strip()
                if key == 'requires':
                    info[key] = [r.strip() for r in value.split(',') if r.strip()] if value else []
                else:
                    info[key] = value
        return info if info else None

if __name__ == '__main__':
    analyzer = DependencyAnalyzer('pip')
    print(json.dumps(analyzer.get_installed_packages()[:5], indent=2))

use std::collections::VecDeque;
use std::sync::{Arc, Condvar, Mutex};
use std::thread;
use std::time::{Duration, Instant};
use uuid::Uuid;

#[derive(Clone, Debug)]
pub struct Job<T> {
    pub id: String,
    pub data: T,
    pub priority: u8,
    pub max_retries: u32,
    pub retries: u32,
    pub scheduled_at: Instant,
}

pub enum JobResult {
    Success,
    Retry(Duration),
    Failed(String),
}

pub struct JobQueue<T: Send + 'static> {
    queue: Arc<Mutex<VecDeque<Job<T>>>>>,
    condvar: Arc<Condvar>,
    workers: usize,
    shutdown: Arc<Mutex<bool>>,
}

impl<T: Send + 'static> JobQueue<T> {
    pub fn new(workers: usize) -> Self {
        JobQueue {
            queue: Arc::new(Mutex::new(VecDeque::new())),
            condvar: Arc::new(Condvar::new()),
            workers,
            shutdown: Arc::new(Mutex::new(false)),
        }
    }

    pub fn enqueue(&self, job: Job<T>) {
        let mut queue = self.queue.lock().unwrap();
        let pos = queue.iter().position(|j| j.priority < job.priority).unwrap_or(queue.len());
        queue.insert(pos, job);
        self.condvar.notify_one();
    }

    pub fn shutdown(&self) {
        let mut s = self.shutdown.lock().unwrap();
        *s = true;
        self.condvar.notify_all();
    }
}

