package circuitbreaker

import (
	"errors"
	"sync"
	"time"
)

type State int

const (
	StateClosed State = iota
	StateOpen
	StateHalfOpen
)

var ErrCircuitOpen = errors.New("circuit breaker está aberto")

type CircuitBreaker struct {
	maxFailures   uint32
	timeout       time.Duration
	state         State
	failures      uint32
	mu            sync.RWMutex
}

type Config struct {
	MaxFailures      uint32
	Timeout          time.Duration
	HalfOpenMaxCalls uint32
}

func New(config Config) *CircuitBreaker {
	return &CircuitBreaker{
		maxFailures: config.MaxFailures,
		timeout:     config.Timeout,
		state:       StateClosed,
	}
}

func (cb *CircuitBreaker) Execute(fn func() error) error {
	if err := cb.canExecute(); err != nil {
		return err
	}
	err := fn()
	cb.recordResult(err)
	return err
}

func (cb *CircuitBreaker) canExecute() error {
	cb.mu.Lock()
	defer cb.mu.Unlock()
	switch cb.state {
	case StateOpen:
		if time.Since(cb.lastFailureTime) > cb.timeout {
			cb.toHalfOpen()
			return nil
		}
		return ErrCircuitOpen
	case StateHalfOpen:
		return nil
	case StateClosed:
		return nil
	}
	return nil
}

func (cb *CircuitBreaker) recordResult(err error) {
	cb.mu.Lock()
	defer cb.mu.Unlock()
	if err != nil {
		cb.failures++
		if cb.failures >= cb.maxFailures {
			cb.toOpen()
		}
	} else {
		cb.failures = 0
	}
}

func (cb *CircuitBreaker) toOpen() {
	cb.state = StateOpen
}

func (cb *CircuitBreaker) toHalfOpen() {
	cb.state = StateHalfOpen
}

import { Readable } from 'stream';

interface ExportConfig {
  format: 'csv' | 'json' | 'xml';
  data: any[];
  filename?: string;
}

interface ExportResult {
  buffer: Buffer;
  filename: string;
  mimeType: string;
}

export class DataExporter {
  async export(config: ExportConfig): Promise<ExportResult> {
    switch (config.format) {
      case 'csv':
        return this.exportCSV(config);
      case 'json':
        return this.exportJSON(config);
      case 'xml':
        return this.exportXML(config);
      default:
        throw new Error(`Formato não suportado: ${config.format}`);
    }
  }

  private exportCSV(config: ExportConfig): ExportResult {
    const headers = Object.keys(config.data[0] || {});
    let csv = headers.join(',') + '\n';
    for (const row of config.data) {
      csv += headers.map(h => String(row[h] ?? '').replace(/,/g, '\,')).join(',') + '\n';
    }
    return {
      buffer: Buffer.from(csv, 'utf-8'),
      filename: `${config.filename || 'export'}.csv`,
      mimeType: 'text/csv'
    };
  }

  private exportJSON(config: ExportConfig): ExportResult {
    const json = JSON.stringify(config.data, null, 2);
    return {
      buffer: Buffer.from(json, 'utf-8'),
      filename: `${config.filename || 'export'}.json`,
      mimeType: 'application/json'
    };
  }

  private exportXML(config: ExportConfig): ExportResult {
    const root = 'root';
    const itemName = 'item';
    let xml = '<?xml version="1.0" encoding="UTF-8"?>\n';
    xml += `<${root}>\n`;
    for (const item of config.data) {
      xml += `  <${itemName}>\n`;
      for (const [key, value] of Object.entries(item)) {
        xml += `    <${key}>${String(value ?? '').replace(/</g, '&lt;')}</${key}>\n`;
      }
      xml += `  </${itemName}>\n`;
    }
    xml += `</${root}>\n`;
    return {
      buffer: Buffer.from(xml, 'utf-8'),
      filename: `${config.filename || 'export'}.xml`,
      mimeType: 'application/xml'
    };
  }
}

