#!/usr/bin/env python3
import psutil
import time
import json
from datetime import datetime

def get_process_info():
    processes = []
    for proc in psutil.process_iter(['pid', 'name', 'cpu_percent', 'memory_percent', 'status']):
        try:
            processes.append(proc.info)
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            pass
    return processes

def monitor_system(interval=5):
    while True:
        timestamp = datetime.now().isoformat()
        cpu = psutil.cpu_percent(interval=1)
        memory = psutil.virtual_memory().percent
        disk = psutil.disk_usage('/').percent
        processes = get_process_info()
        top_processes = sorted(processes, key=lambda x: x.get('cpu_percent', 0), reverse=True)[:10]
        data = {
            'timestamp': timestamp,
            'cpu_percent': cpu,
            'memory_percent': memory,
            'disk_percent': disk,
            'top_processes': top_processes
        }
        print(json.dumps(data, indent=2))
        time.sleep(interval)

if __name__ == '__main__':
    monitor_system()

package email

import (
	"fmt"
	"net/smtp"
)

type Config struct {
	Host     string
	Port     int
	Username string
	Password string
	From     string
}

type Service struct {
	config Config
}

func NewService(config Config) *Service {
	return &Service{config: config}
}

func (s *Service) Send(to []string, subject, body string) error {
	addr := fmt.Sprintf("%s:%d", s.config.Host, s.config.Port)
	msg := []byte(fmt.Sprintf("To: %s\r\nSubject: %s\r\n\r\n%s",
		to, subject, body))
	auth := smtp.PlainAuth("", s.config.Username, s.config.Password, s.config.Host)
	return smtp.SendMail(addr, auth, s.config.From, to, msg)
}

func (s *Service) SendHTML(to []string, subject, htmlBody string) error {
	headers := fmt.Sprintf("To: %s\r\nContent-Type: text/html; charset=UTF-8\r\nSubject: %s\r\n\r\n", to, subject)
	msg := []byte(headers + htmlBody)
	addr := fmt.Sprintf("%s:%d", s.config.Host, s.config.Port)
	auth := smtp.PlainAuth("", s.config.Username, s.config.Password, s.config.Host)
	return smtp.SendMail(addr, auth, s.config.From, to, msg)
}

import { Redis } from 'ioredis';

interface RateLimitConfig {
  windowMs: number;
  maxRequests: number;
  keyPrefix?: string;
}

interface RateLimitResult {
  allowed: boolean;
  remaining: number;
  resetTime: number;
  retryAfter?: number;
}

export class DistributedRateLimiter {
  private redis: Redis;
  private config: RateLimitConfig;

  constructor(redis: Redis, config: RateLimitConfig) {
    this.redis = redis;
    this.config = {
      keyPrefix: 'ratelimit:',
      ...config
    };
  }

  async check(key: string): Promise<RateLimitResult> {
    const now = Date.now();
    const windowStart = now - this.config.windowMs;
    const redisKey = `${this.config.keyPrefix}${key}`;
    const pipeline = this.redis.pipeline();
    pipeline.zremrangebyscore(redisKey, 0, windowStart);
    pipeline.zcard(redisKey);
    pipeline.zadd(redisKey, now, `${now}-${Math.random()}`);
    pipeline.pexpire(redisKey, this.config.windowMs);
    const results = await pipeline.exec();
    const currentCount = results?.[1]?.[1] as number || 0;
    const allowed = currentCount < this.config.maxRequests;
    const remaining = Math.max(0, this.config.maxRequests - currentCount - 1);
    const resetTime = now + this.config.windowMs;
    return {
      allowed,
      remaining,
      resetTime,
      retryAfter: allowed ? undefined : Math.ceil(this.config.windowMs / 1000)
    };
  }
}

#!/usr/bin/env python3
import uuid
import argparse
import json
from typing import List

def generate_uuids(count: int = 1, version: int = 4) -> List[str]:
    uuids = []
    for _ in range(count):
        if version == 1:
            uuids.append(str(uuid.uuid1()))
        elif version == 4:
            uuids.append(str(uuid.uuid4()))
        elif version == 5:
            uuids.append(str(uuid.uuid5(uuid.NAMESPACE_DNS, 'example.com')))
        else:
            raise ValueError(f'Versão {version} não suportada')
    return uuids

def main():
    parser = argparse.ArgumentParser(description='Gerador de UUIDs')
    parser.add_argument('-c', '--count', type=int, default=1, help='Quantidade de UUIDs')
    parser.add_argument('-v', '--version', type=int, default=4, choices=[1, 4, 5], help='Versão do UUID')
    parser.add_argument('-f', '--format', choices=['plain', 'json'], default='plain', help='Formato de saída')
    args = parser.parse_args()
    uuids = generate_uuids(args.count, args.version)
    if args.format == 'json':
        print(json.dumps({'uuids': uuids, 'version': args.version, 'count': len(uuids)}, indent=2))
    else:
        for uid in uuids:
            print(uid)

if __name__ == '__main__':
    main()

use std::collections::VecDeque;
use std::sync::{Arc, Condvar, Mutex};
use std::time::{Duration, Instant};
use uuid::Uuid;

#[derive(Clone, Debug)]
pub struct Message {
    pub id: String,
    pub payload: String,
    pub priority: u8,
    pub created_at: Instant,
    pub ttl: Option<Duration>,
}

impl Message {
    pub fn new(payload: String) -> Self {
        Message {
            id: Uuid::new_v4().to_string(),
            payload,
            priority: 5,
            created_at: Instant::now(),
            ttl: None,
        }
    }
    pub fn with_priority(mut self, priority: u8) -> Self {
        self.priority = priority.clamp(1, 10);
        self
    }
    pub fn with_ttl(mut self, ttl: Duration) -> Self {
        self.ttl = Some(ttl);
        self
    }
    pub fn is_expired(&self) -> bool {
        self.ttl.map_or(false, |ttl| self.created_at.elapsed() > ttl)
    }
}

pub struct MessageQueue {
    messages: Arc<Mutex<VecDeque<Message>>>,
    condvar: Arc<Condvar>,
}

impl MessageQueue {
    pub fn new() -> Self {
        MessageQueue {
            messages: Arc::new(Mutex::new(VecDeque::new())),
            condvar: Arc::new(Condvar::new()),
        }
    }
    pub fn push(&self, message: Message) {
        let mut queue = self.messages.lock().unwrap();
        let pos = queue.iter().position(|m| m.priority < message.priority).unwrap_or(queue.len());
        queue.insert(pos, message);
        self.condvar.notify_one();
    }
    pub fn pop(&self, timeout: Duration) -> Option<Message> {
        let mut queue = self.messages.lock().unwrap();
        let deadline = Instant::now() + timeout;
        loop {
            queue.retain(|m| !m.is_expired());
            if let Some(msg) = queue.pop_front() {
                if !msg.is_expired() {
                    return Some(msg);
                }
            }
            let now = Instant::now();
            if now >= deadline {
                return None;
            }
            let wait_time = deadline.duration_since(now);
            let result = self.condvar.wait_timeout(queue, wait_time).unwrap();
            queue = result.0;
            if result.1.timed_out() {
                return None;
            }
        }
    }
    pub fn len(&self) -> usize {
        self.messages.lock().unwrap().len()
    }
}
